<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$new=(string)($_POST['statut']??'');$allowed=['initiee','pieces_attendues','transmise','acceptee','refusee','annulee'];if(in_array($new,$allowed,true)){$s=$db->prepare('SELECT statut FROM souscriptions WHERE id=?');$s->execute([$id]);$old=(string)$s->fetchColumn();$db->prepare('UPDATE souscriptions SET statut=? WHERE id=?')->execute([$new,$id]);$db->prepare('INSERT INTO suivis_dossiers(souscription_id,utilisateur_id,ancien_statut,nouveau_statut,commentaire) VALUES(?,?,?,?,?)')->execute([$id,$_SESSION['user']['id'],$old,$new,trim((string)($_POST['commentaire']??''))?:null]);audit('CHANGEMENT_STATUT','souscription',$id,$old.' -> '.$new);flash('success','Statut mis à jour.');}redirect('souscriptions/index.php');}$rows=$db->query("SELECT s.*,o.prime_totale,p.nom produit,co.raison_sociale compagnie,(SELECT COUNT(*) FROM suivis_dossiers sd WHERE sd.souscription_id=s.id) nb_suivis,(SELECT id FROM contrats c WHERE c.souscription_id=s.id) contrat_id FROM souscriptions s JOIN offres_devis o ON o.id=s.offre_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id ORDER BY s.date_souscription DESC")->fetchAll();$title='Souscriptions';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Souscriptions</h1><p class="text-secondary">Suivi des dossiers transmis aux compagnies</p></div></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Numéro</th><th>Offre</th><th>Prime</th><th>Statut</th><th>Suivis</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['numero_souscription']) ?></td><td><strong><?= e($r['produit']) ?></strong><div class="small"><?= e($r['compagnie']) ?></div></td><td><?= number_format((float)$r['prime_totale'],0,',',' ') ?> FCFA</td><td><?= e($r['statut']) ?></td><td><?= $r['nb_suivis'] ?></td><td class="text-end"><form method="post" class="d-inline-flex gap-1"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $r['id'] ?>"><select class="form-select form-select-sm" name="statut"><?php foreach(['initiee','pieces_attendues','transmise','acceptee','refusee','annulee'] as $st): ?><option <?= $r['statut']===$st?'selected':'' ?>><?= $st ?></option><?php endforeach ?></select><input class="form-control form-control-sm" name="commentaire" placeholder="Commentaire"><button class="btn btn-sm btn-outline-primary">Mettre à jour</button></form> <?php if($r['statut']==='acceptee'&&!$r['contrat_id']): ?><a class="btn btn-sm btn-success" href="<?= APP_URL ?>/contrats/form.php?souscription_id=<?= $r['id'] ?>">Créer contrat</a><?php endif; ?></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
